import {educationBadges} from './career-opportunities-ui.js';
import {occupationById} from './occupation-data.js';
import {salaryLifestyleLink} from './salary-ui.js?v=0.31.0';
import {salaryAtStage,formatSalary} from './salary-progression.js?v=0.31.0';
import {directions} from './content.js?v=0.31.0';
import {careers,pathCareers,wageCenter,wageCaption} from './finance-data.js?v=0.31.0';
import {majors} from './catalog-data.js?v=0.31.0';
import {educationCostsPanel,usd} from './finance-ui.js?v=0.31.0';
import {texasRequirements} from './texas-requirements.js?v=0.31.0';
import {escapeHTML as h} from './model.js?v=0.31.0';
import {occupationCatalogPage} from './occupation-ui.js?v=0.31.0';
export const credentialNames={bachelor:'Bachelor’s typically',associate:'Associate / certificate',graduate:'Graduate / professional',training:'Apprenticeship / occupational training',varies:'Several education routes'};
const more=body=>`<details class="more-info"><summary>More info</summary><div>${body}</div></details>`;
const careerCard=c=>`<article class="catalog-card"><span class="overline">SPECIFIC CAREER · ${h(credentialNames[c.credentialLevel])}</span><h3><a href="#/career/${c.id}">${h(c.title)}</a></h3>${educationBadges(occupationById(c.id))}<p>${h(texasRequirements[c.id].typicalEntry)}</p><div class="catalog-wage"><strong>${formatSalary(salaryAtStage(c.id))}</strong><span>Entry level / year · planning estimate</span></div><div class="catalog-card-links"><a href="#/career/${c.id}">Texas requirements, costs & aid ↗</a>${salaryLifestyleLink(c.id,'entry','career')}</div></article>`;
export function catalogPage(view={},state){if(view.type==='occupations'||view.activity||view.setting)return occupationCatalogPage(view,state);const q=(view.search||'').trim().toLowerCase(),type=view.type||'careers',path=view.path||'',level=view.level||'';let records=type==='careers'?careers:majors;
 records=records.filter(x=>{const pathIds=type==='careers'?Object.entries(pathCareers).filter(([,ids])=>ids.includes(x.id)).map(([id])=>id):x.paths;const hay=[x.title,...(x.educationRoutes?.routes||[]),...pathIds.map(id=>directions.find(d=>d.id===id)?.title||'')].join(' ').toLowerCase();return (!q||hay.includes(q))&&(!path||pathIds.includes(path))&&(type!=='careers'||!level||x.credentialLevel===level);});
 return `<div class="page-intro catalog-intro"><div><span class="eyebrow">A WIDER WORLD TO EXPLORE</span><h1>Find a possibility.<br>Follow your curiosity.</h1><p class="intro-copy">College. Apprenticeships. Practical training. Every career has Austin pay and Texas requirements.</p></div></div><p><a class="text-link" href="#/degree-careers">Explore the expanded 404-profile college career inventory →</a></p><div class="catalog-banner"><div><b>${directions.length}</b><span>broad pathways</span></div><div><b>${majors.length}</b><span>fields of study</span></div><div><b>${careers.length}</b><span>specific careers</span></div><p>Many routes. Room to change your mind.</p></div><section class="catalog-filters" aria-label="Catalog filters"><div class="catalog-tabs" role="group" aria-label="Browse type">${[['majors','College fields of study'],['careers','All careers & training']].map(([id,label])=>`<button data-action="catalog-type" data-id="${id}" aria-pressed="${type===id}">${label}</button>`).join('')}</div><div class="catalog-filter-row"><div class="field"><label class="label" for="catalog-search">Search by subject or career</label><input id="catalog-search" type="search" placeholder="Try biology, electrical, history…" value="${h(view.search||'')}"></div><div class="field"><label class="label" for="catalog-path">Broad pathway</label><select id="catalog-path" data-catalog="path"><option value="">All pathways</option>${directions.map(d=>`<option value="${d.id}" ${path===d.id?'selected':''}>${h(d.title)}</option>`).join('')}</select></div>${type==='careers'?`<div class="field"><label class="label" for="catalog-level">Typical preparation route</label><select id="catalog-level" data-catalog="level"><option value="">All preparation routes</option>${Object.entries(credentialNames).map(([id,label])=>`<option value="${id}" ${level===id?'selected':''}>${h(label)}</option>`).join('')}</select></div>`:''}</div>${more('<p>Connections are editorial exploration prompts. They do not rank aptitude or guarantee that a degree qualifies you for a job.</p>')}</section><div class="section-title"><h2>${records.length} ${type==='careers'?(records.length===1?'career':'careers'):(records.length===1?'field of study':'fields of study')}</h2><a class="text-link" href="#/directions">Compare broad pathways ↗</a></div><div class="catalog-grid">${records.map(x=>type==='careers'?careerCard(x):`<article class="catalog-card"><span class="overline">COLLEGE FIELD OF STUDY</span><h3><a href="#/major/${x.slug}">${h(x.title)}</a></h3><p>${x.paths.map(id=>h(directions.find(d=>d.id===id).title)).join(' · ')}</p><p>${x.careers.length?`${x.careers.length} directly connected career example${x.careers.length===1?'':'s'}`:'Explore related career examples within this field’s pathways'}</p><a class="text-link" href="#/major/${x.slug}">Study, requirements, costs, aid & careers ↗</a></article>`).join('')||'<div class="empty-state"><h3>No matches yet.</h3><p>Try a broader term or clear the pathway and preparation filters.</p><button class="button secondary" data-action="catalog-clear">Clear filters</button></div>'}</div>`;
}
export function majorPage(slug,state){const m=majors.find(x=>x.slug===slug);if(!m)return '<h1>Subject not found.</h1><a href="#/catalog">Browse catalog</a>';const paths=m.paths.map(id=>directions.find(d=>d.id===id)),direct=m.careers.length>0,ids=direct?m.careers:[...new Set(m.paths.flatMap(id=>pathCareers[id]||[]))],cs=ids.map(id=>careers.find(c=>c.id===id));return `<div class="page-intro catalog-intro"><div><span class="eyebrow">COLLEGE STUDY · AUSTIN CONTEXT</span><h1>${h(m.title)}</h1><p class="intro-copy">What you could learn. Where it could lead.</p></div><a class="button secondary" href="#/catalog">Browse catalog ↗</a></div><section class="context-panel" data-coverage="educationRoutes"><span class="overline">EDUCATION</span><h2>Build knowledge. Keep options open.</h2><div class="tags">${paths.map(d=>`<a class="tag" href="#/path/${d.id}">${h(d.title)} ↗</a>`).join('')}</div>${more(paths.map(d=>`<p>${h(d.learn)}</p>`).join('')+'<p>A subject may be a major, concentration, or minor. Admission and graduation rules belong to a specific degree program. These are study connections, not verified degree-to-license mappings.</p>')}</section><section class="context-panel" data-coverage="requirements"><span class="overline">TEXAS CAREER REQUIREMENTS</span><h2>A subject opens several doors.</h2><div class="requirements-grid">${cs.map(c=>`<a class="requirement-mini" href="#/career/${c.id}"><h3>${h(c.title)}</h3><p>${h(texasRequirements[c.id].summary)}</p><span>See the Texas route →</span></a>`).join('')}</div></section>${educationCostsPanel(state,m.id)}<section class="context-panel" data-coverage="earnings"><span class="overline">AUSTIN PAY</span><h2>One major. Many possible careers.</h2><div class="catalog-grid">${cs.map(careerCard).join('')}</div>${more(`<p>${direct?'These examples connect to the listed study routes.':'These examples connect through broader pathways; this subject alone does not prepare you for each role.'} Wages describe occupations, not all graduates of a major. There is no single major salary or guaranteed outcome.</p>`)}</section><section class="counselor-card"><h2>Try something small.</h2><p>${h(paths[0].activity)}</p>${more(`<p>${h(m.question)}</p>`)}<a href="#/results" class="text-link">Connect my interests & evidence →</a></section>`;}
